#include <vector>
#include <string>
#include <unordered_set>

class Solution {
public:
    bool reportSpam(std::vector<std::string>& message, std::vector<std::string>& bannedWords) {
        std::unordered_set<std::string> banned(bannedWords.begin(), bannedWords.end());
        int count = 0;
        for (const auto& w : message) {
            if (banned.count(w)) {
                count++;
                if (count >= 2) return true;
            }
        }
        return false;
    }
};

import java.util.*;

class Solution {
    public boolean reportSpam(String[] message, String[] bannedWords) {
        Set<String> banned = new HashSet<>(Arrays.asList(bannedWords));
        int count = 0;
        for (String w : message) {
            if (banned.contains(w)) {
                count++;
                if (count >= 2) return true;
            }
        }
        return false;
    }
}

